function toman(n) {
  return n.toLocaleString("fa-IR") + " تومان";
}
function sessionPrice(pkgKey) {
  return Math.round(TREATMENT_PACKAGES[pkgKey].price / TREATMENT_PACKAGES[pkgKey].sessions);
}
function sessionId(pkgKey, num) {
  return `${pkgKey}-${num}`;
}

